-- Generated by digit. Numeric workspace modes and floating-window snapping.
-- Geometry below is compositor-independent and tested with a stock Lua interpreter.
local G = {}
local function round(n) return math.floor(n + 0.5) end
local function clamp(n, lo, hi) return math.max(lo, math.min(n, hi)) end
function G.monitor(m)
    local w, h = m.width / m.scale, m.height / m.scale
    if (m.transform or 0) % 2 == 1 then w, h = h, w end
    return { x = m.x, y = m.y, w = round(w), h = round(h), name = m.name }
end
function G.workarea(m, reserved, outer)
    local l, r = reserved.left or 0, reserved.right or 0
    local t, b = reserved.top or 0, reserved.bottom or 0
    return { x = l + outer.left, y = t + outer.top,
        w = math.max(1, m.w - l - r - outer.left - outer.right),
        h = math.max(1, m.h - t - b - outer.top - outer.bottom) }
end
function G.inset(r, border)
    border = border or 0
    return { x = r.x + border, y = r.y + border, w = math.max(1, r.w - 2 * border), h = math.max(1, r.h - 2 * border) }
end
function G.rect(area, zone, inner, border)
    local x, y = math.ceil(area.x), math.ceil(area.y)
    local right, bottom = math.floor(area.x + area.w), math.floor(area.y + area.h)
    if zone ~= 'max' then
        local left = zone == 'left' or zone == 'tl' or zone == 'bl'
        local gap = type(inner) == 'table' and ((left and inner.right or inner.left) or inner.left or 0) or inner
        local mid = area.x + math.floor(area.w / 2)
        if left then right = round(mid - gap / 2) else x = round(mid + gap / 2) end
        if zone ~= 'left' and zone ~= 'right' then
            local top = zone == 'tl' or zone == 'tr'
            gap = type(inner) == 'table' and ((top and inner.bottom or inner.top) or inner.top or 0) or inner
            mid = area.y + math.floor(area.h / 2)
            if top then bottom = round(mid - gap / 2) else y = round(mid + gap / 2) end
        end
    end
    return G.inset({ x = x, y = y, w = math.max(1, right - x), h = math.max(1, bottom - y) }, border)
end
-- A seam is blocked only at the cursor's projection onto it, including staggered outputs.
function G.edges(m, monitors, x, y)
    local e = { left = true, right = true, top = true, bottom = true }
    for _, n in ipairs(monitors) do
        if n.name ~= m.name then
            if y >= n.y and y < n.y + n.h then
                if math.abs(n.x + n.w - m.x) <= 1 then e.left = false end
                if math.abs(m.x + m.w - n.x) <= 1 then e.right = false end
            end
            if x >= n.x and x < n.x + n.w then
                if math.abs(n.y + n.h - m.y) <= 1 then e.top = false end
                if math.abs(m.y + m.h - n.y) <= 1 then e.bottom = false end
            end
        end
    end
    return e
end
function G.zone(x, y, w, h, edges, previous)
    local function choose(edge, corner)
        local l, r = edges.left and x <= edge, edges.right and x >= w - edge
        local t, b = edges.top and y <= edge, edges.bottom and y >= h - edge
        if edges.left and edges.top and ((l and y <= corner) or (t and x <= corner)) then return 'tl' end
        if edges.right and edges.top and ((r and y <= corner) or (t and x >= w - corner)) then return 'tr' end
        if edges.left and edges.bottom and ((l and y >= h - corner) or (b and x <= corner)) then return 'bl' end
        if edges.right and edges.bottom and ((r and y >= h - corner) or (b and x >= w - corner)) then return 'br' end
        if l then return 'left' end
        if r then return 'right' end
        if t then return 'max' end
    end
    if (not edges.left and x <= 12) or (not edges.right and x >= w - 12)
        or (not edges.top and y <= 12) or (not edges.bottom and y >= h - 12) then return nil end
    local fresh = choose(12, 64)
    -- Keep the old zone until the cursor leaves a wider band; never retain across a seam.
    if previous and choose(24, 80) == previous then return previous end
    return fresh
end
function G.cascade(area, index, occupied)
    local x, y = math.ceil(area.x), math.ceil(area.y)
    area = { x = x, y = y, w = math.max(1, math.floor(area.x + area.w) - x), h = math.max(1, math.floor(area.y + area.h) - y) }
    local w, h = math.min(1280, round(area.w * 0.7)), math.min(860, round(area.h * 0.7))
    w, h = math.max(1, w), math.max(1, h)
    local dx, dy = math.max(0, area.w - w), math.max(0, area.h - h)
    -- A window alone on the workspace sits in the middle.
    if occupied and #occupied == 0 then
        return { x = area.x + math.floor(dx / 2), y = area.y + math.floor(dy / 2), w = w, h = h }
    end
    -- Co-prime steps traverse the available positions without a short repeating stack.
    occupied = occupied or {}
    for offset = 0, #occupied do
        local step = index + offset
        local r = { x = area.x + (step * 31 % (math.floor(dx) + 1)),
            y = area.y + (step * 23 % (math.floor(dy) + 1)), w = w, h = h }
        local covered = false
        for _, old in ipairs(occupied) do
            if old.x == r.x and old.y == r.y then covered = true; break end
        end
        if not covered or offset == #occupied then return r end
    end
end
-- Centred in the area at a new scale, never larger than the area or too small to use.
function G.scaled(area, size, scale)
    local w = clamp(round(size.w * scale), math.min(240, area.w), area.w)
    local h = clamp(round(size.h * scale), math.min(160, area.h), area.h)
    return { x = area.x + math.floor((area.w - w) / 2), y = area.y + math.floor((area.h - h) / 2), w = w, h = h }
end
-- The same place and share of the work area on another monitor.
function G.relative(from, to, r)
    local w = clamp(round(r.w / from.w * to.w), 1, to.w)
    local h = clamp(round(r.h / from.h * to.h), 1, to.h)
    return { x = clamp(to.x + round((r.x - from.x) / from.w * to.w), to.x, to.x + to.w - w),
        y = clamp(to.y + round((r.y - from.y) / from.h * to.h), to.y, to.y + to.h - h), w = w, h = h }
end
-- Whether a window already fills this rectangle, allowing for rounding.
function G.fills(r, x, y, w, h)
    return math.abs(r.x - x) <= 2 and math.abs(r.y - y) <= 2 and math.abs(r.w - w) <= 2 and math.abs(r.h - h) <= 2
end
function G.restore(saved, cursor, grab, monitor)
    return { x = round(cursor.x - monitor.x - saved.w * grab.x),
        y = round(cursor.y - monitor.y - saved.h * grab.y), w = saved.w, h = saved.h }
end
if not hl then return G end

local M = { geometry = G }
local default_mode = {{layout}}
local modes = {{modes}}
local underlying = {{underlying}}
local snap_enabled = {{snap}}
local owned_tag = 'digit-mode-floated'
local saved_prefix = 'digit-snap:'
local cascades, saved = {}, {}
local drag, timer, preview
local changing = false
local pending, opening = {}, {}
local function tag(w, value)
    hl.dispatch(hl.dsp.window.tag({ window = w, tag = value }))
end
local function has_tag(w, value)
    for _, t in ipairs(w.tags or {}) do if t == value then return true end end
    return false
end
local function numbered(ws) return ws and not ws.special and ws.id and ws.id > 0 end
local function floating(ws) return numbered(ws) and (modes[ws.id] or default_mode) == 'floating' end
local function gaps()
    return hl.get_config('general.gaps_out'), hl.get_config('general.gaps_in')
end
local function area(m)
    local outer, inner = gaps()
    return G.workarea(G.monitor(m), m.reserved, outer), inner, hl.get_config('general.border_size')
end
local function place(w, m, r)
    hl.dispatch(hl.dsp.window.resize({ window = w, x = r.w, y = r.h, relative = false }))
    hl.dispatch(hl.dsp.window.move({ window = w, x = m.x + r.x, y = m.y + r.y, relative = false }))
end
local function remember(w)
    if saved[w.address] then return end
    local a, s = w.at, w.size
    saved[w.address] = { x = a.x, y = a.y, w = s.x, h = s.y }
    tag(w, '+' .. saved_prefix .. string.format('%d:%d:%d:%d', a.x, a.y, s.x, s.y))
end
local function forget(w)
    saved[w.address] = nil
    for _, t in ipairs(w.tags or {}) do
        if t:sub(1, #saved_prefix) == saved_prefix then tag(w, '-' .. t) end
    end
end
local function rebuild_saved(w)
    for _, t in ipairs(w.tags or {}) do
        local x, y, width, height = t:match('^digit%-snap:(%-?%d+):(%-?%d+):(%d+):(%d+)$')
        if x then saved[w.address] = { x = tonumber(x), y = tonumber(y), w = tonumber(width), h = tonumber(height) } end
    end
end
local function show(m, r, zone)
    if m and not m.name:match('^[%w_.%-]+$') then m = nil end
    local key = m and (m.name .. ':' .. zone .. ':' .. r.x .. ':' .. r.y .. ':' .. r.w .. ':' .. r.h)
    if key == preview then return end
    preview = key
    if key then
        -- exec_cmd uses /bin/sh. Accept only a connector token, never interpolate shell text.
        hl.exec_cmd(string.format('digit msg snap-zone %s %d %d %d %d', m.name, r.x, r.y, r.w, r.h))
    else
        hl.exec_cmd('digit msg snap-zone off')
    end
end
local function cancel()
    local armed = drag ~= nil
    drag = nil
    if timer then timer:set_enabled(false) end
    if armed and not preview then hl.exec_cmd('digit msg snap-zone off') else show(nil) end
end
local function eligible(w) return w and w.mapped and w.floating and (w.fullscreen or 0) == 0 end
local function locate(cursor)
    local monitors = {}
    local under
    for _, m in ipairs(hl.get_monitors()) do
        if m.enabled and not m.is_mirror then
            local box = G.monitor(m)
            monitors[#monitors + 1] = box
            if cursor.x >= box.x and cursor.x < box.x + box.w and cursor.y >= box.y and cursor.y < box.y + box.h then under = m end
        end
    end
    return under, monitors
end
local function poll()
    if not drag then return end
    local w = drag.window
    if not eligible(w) or w.workspace ~= drag.workspace then cancel(); return end
    local cursor = hl.get_cursor_pos()
    if not cursor then cancel(); return end
    local m, monitors = locate(cursor)
    if not m then drag.zone = nil; show(nil); return end
    local box = G.monitor(m)
    local edges = G.edges(box, monitors, cursor.x, cursor.y)
    local previous = drag.monitor == m and drag.zone or nil
    local zone = G.zone(cursor.x - box.x, cursor.y - box.y, box.w, box.h, edges, previous)
    drag.monitor, drag.zone = m, zone
    if zone then
        local work, inner, border = area(m)
        drag.rect = G.rect(work, zone, inner, border)
        show(m, drag.rect, zone)
    else
        drag.rect = nil
        show(nil)
    end
end
local function finish()
    if not drag then return end
    poll() -- The release can land between two 33ms samples.
    local d = drag
    cancel()
    if not d or not eligible(d.window) then return end
    local w, cursor = d.window, hl.get_cursor_pos()
    if d.zone then
        remember(w)
        place(w, d.monitor, d.rect)
    elseif saved[w.address] and cursor and (math.abs(cursor.x - d.start.x) > 12 or math.abs(cursor.y - d.start.y) > 12) then
        local m = locate(cursor)
        if m then place(w, m, G.restore(saved[w.address], cursor, d.grab, G.monitor(m))); forget(w) end
    end
end
-- The dispatcher requests this same callback on release, even if Super is released first.
-- Keep the bind's press/release latch separate from cancellation of its polling state.
function M.drag()
    local pressed = false
    return function()
        if pressed then
            pressed = false
            local ok, result = pcall(function()
                local result = hl.dispatch(hl.dsp.window.drag())
                finish()
                return result
            end)
            if not ok then cancel(); error(result) end
            return result
        end
        pressed = true
        local was_floating = {}
        for _, w in ipairs(hl.get_windows()) do if eligible(w) then was_floating[w.address] = true end end
        local result = hl.dispatch(hl.dsp.window.drag())
        local w, cursor = hl.get_active_window(), hl.get_cursor_pos()
        -- drag() focuses the hit-tested target. Do not arm for a tiled target temporarily floated
        -- by native dragging, or a click in empty space which left the focus unchanged.
        if snap_enabled and w and was_floating[w.address] and cursor then
            local a, s = w.at, w.size
            if cursor.x >= a.x and cursor.y >= a.y and cursor.x < a.x + s.x and cursor.y < a.y + s.y then
                drag = { window = w, workspace = w.workspace, start = cursor,
                    grab = { x = clamp((cursor.x - a.x) / s.x, 0, 1), y = clamp((cursor.y - a.y) / s.y, 0, 1) } }
                if not timer then timer = hl.timer(function()
                    local ok = pcall(poll)
                    if not ok then cancel() end
                end, { type = 'repeat', timeout = 33 }) else timer:set_enabled(true) end
            end
        end
        return result
    end
end
function M.snap(zone, always)
    return function()
        if not snap_enabled and not always then return end
        local w = hl.get_active_window()
        if not eligible(w) or not w.monitor then return end
        cancel()
        local scale = ({ center = 1, grow = 1.2, shrink = 0.8 })[zone]
        if scale then
            local work, _, border = area(w.monitor)
            remember(w)
            place(w, w.monitor, G.scaled(G.inset(work, border), { w = w.size.x, h = w.size.y }, scale))
        elseif zone == 'restore' then
            local back = saved[w.address]
            if back then
                local m = w.monitor
                place(w, m, { x = back.x - m.x, y = back.y - m.y, w = back.w, h = back.h })
                forget(w)
            end
        else
            local work, inner, border = area(w.monitor)
            remember(w)
            place(w, w.monitor, G.rect(work, zone, inner, border))
        end
    end
end

-- On a floating workspace the side arrows snap; everywhere else they do what they always did.
function M.arrow(zone, otherwise)
    local snap = M.snap(zone)
    return function()
        local w = hl.get_active_window()
        if snap_enabled and eligible(w) and floating(w.workspace) then return snap() end
        if type(otherwise) == 'function' then return otherwise() end
        return hl.dispatch(otherwise)
    end
end
-- Everything on a floating workspace floats, so there the float key maximizes and restores.
function M.float_key(action)
    local maximize, restore = M.snap('max', true), M.snap('restore', true)
    return function()
        local w = hl.get_active_window()
        if not (w and floating(w.workspace)) then return hl.dispatch(action) end
        if not eligible(w) or not w.monitor then return end
        local m = w.monitor
        local work, inner, border = area(m)
        local full = G.rect(work, 'max', inner, border)
        if G.fills(full, w.at.x - m.x, w.at.y - m.y, w.size.x, w.size.y) then return restore() end
        return maximize()
    end
end
function M.to_monitor(step)
    return function()
        local w = hl.get_active_window()
        if not w or not w.monitor then return end
        local list = {}
        for _, m in ipairs(hl.get_monitors()) do
            if m.enabled and not m.is_mirror then list[#list + 1] = m end
        end
        table.sort(list, function(a, b) return a.x < b.x or (a.x == b.x and a.y < b.y) end)
        local at
        for i, m in ipairs(list) do if m.name == w.monitor.name then at = i end end
        if not at or #list < 2 then return end
        local from, to = w.monitor, list[(at - 1 + step) % #list + 1]
        local keep = eligible(w) and { x = w.at.x - from.x, y = w.at.y - from.y, w = w.size.x, h = w.size.y }
        local old = keep and area(from)
        hl.dispatch(hl.dsp.window.move({ monitor = to.name }))
        if keep then
            forget(w)
            place(w, to, G.relative(old, (area(to)), keep))
        end
    end
end

-- Claim every tiled member before floating any member: a group changes as one target.
local function arrange_now(windows)
    local expanded, seen = {}, {}
    local function add(w)
        if w.address and not seen[w.address] then
            seen[w.address] = true
            expanded[#expanded + 1] = w
        end
    end
    for _, w in ipairs(windows) do
        add(w)
        if w.group then for _, member in ipairs(w.group.members or {}) do add(member) end end
    end
    local claim = {}
    for _, w in ipairs(expanded) do
        if w.mapped and numbered(w.workspace) and (w.fullscreen or 0) == 0 then
            if w.pinned then
                if has_tag(w, owned_tag) then tag(w, '-' .. owned_tag) end
            elseif floating(w.workspace) then
                if not w.floating then
                    tag(w, '+' .. owned_tag)
                    claim[#claim + 1] = w
                end
            elseif has_tag(w, owned_tag) then
                tag(w, '-' .. owned_tag)
                forget(w)
                hl.dispatch(hl.dsp.window.float({ window = w, action = 'off' }))
            end
        end
    end
    for _, w in ipairs(claim) do
        hl.dispatch(hl.dsp.window.float({ window = w, action = 'on' }))
        local ws, m = w.workspace, w.monitor
        if m then
            local index = cascades[ws.id] or 0
            cascades[ws.id] = index + 1
            local occupied = {}
            for _, other in ipairs(hl.get_windows()) do
                if other.address ~= w.address and other.workspace == ws and other.floating then
                    local a = other.at
                    occupied[#occupied + 1] = { x = a.x - m.x, y = a.y - m.y }
                end
            end
            local work, _, border = area(m)
            place(w, m, G.cascade(G.inset(work, border), index, occupied))
        end
    end
end
local function arrange(windows)
    if changing then return end
    changing = true
    local ok, err = pcall(arrange_now, windows)
    changing = false
    if not ok then error(err) end
end
hl.on('window.open_early', function(w)
    -- App/dialog float rules have already run; grouping has not.
    opening[w.address] = w.floating
end)
hl.on('window.open', function(w)
    -- This synchronous map callback is before control returns to the event loop/rendering,
    -- after app/dialog rules and layout insertion. open_early cannot float: target.space is nil.
    if opening[w.address] == false and w.floating and w.group and floating(w.workspace) then
        for _, member in ipairs(w.group.members or {}) do
            if has_tag(member, owned_tag) then tag(w, '+' .. owned_tag); break end
        end
    end
    opening[w.address] = nil
    arrange({ w })
end)
hl.on('window.move_to_workspace', function(w)
    if drag and drag.window == w then cancel() end
    pending[w.address] = w
    -- Request a deferred property pass rather than mutate a target midway through transfer.
    -- A disabled empty rule schedules that pass without changing any window or starting a timer.
    hl.window_rule({ name = 'digit-mode-deferred', enabled = false })
end)
hl.on('window.fullscreen', function(w)
    pending[w.address] = w
    hl.window_rule({ name = 'digit-mode-deferred', enabled = false })
end)
hl.on('config.props_refreshed', function()
    local windows = {}
    for _, w in pairs(pending) do windows[#windows + 1] = w end
    pending = {}
    arrange(windows)
end)
hl.on('window.update_state', function(w, changes)
    if changes.pin and has_tag(w, owned_tag) then tag(w, '-' .. owned_tag) end
    if changes.float == false and has_tag(w, owned_tag) then tag(w, '-' .. owned_tag) end
end)
hl.on('window.pin', function(w)
    if w.pinned and has_tag(w, owned_tag) then tag(w, '-' .. owned_tag) end
end)
hl.on('window.close', function(w)
    if drag and drag.window == w then cancel() end
    saved[w.address], pending[w.address], opening[w.address] = nil, nil, nil
end)
for _, event in ipairs({ 'workspace.active', 'workspace.special_active', 'monitor.layout_changed', 'config.unload' }) do hl.on(event, cancel) end
hl.on('config.reloaded', function()
    cancel()
    -- Ownership and restore geometry live on windows, surviving a fresh Lua VM.
    for _, w in ipairs(hl.get_windows()) do rebuild_saved(w) end
    arrange(hl.get_windows())
end)
-- Magnetic edges for free placement; the zones above take over at the screen edge.
if snap_enabled then
    hl.config({ general = { snap = { enabled = true, respect_gaps = true } } })
end
for id, mode in pairs(modes) do
    hl.workspace_rule({ workspace = tostring(id), layout = mode == 'floating' and underlying[id] or mode })
end
return M
